<?php
 namespace Pterodactyl\Services\Dezerx\Minecraft; use Illuminate\Support\Facades\Cache; use Illuminate\Support\Facades\Http; class Geyser { private const DOWNLOAD = 'https://download.geysermc.org/v2/projects/%s/versions/latest/builds/latest/downloads/%s'; private const PROJECT = 'https://download.geysermc.org/v2/projects/%s'; private const TTL = 3600; private const BUILDS = [ 'paper' => 'spigot', 'spigot' => 'spigot', 'fabric' => 'fabric', 'neoforge' => 'neoforge', ]; private const FLOODGATE_BUILDS = [ 'paper' => 'spigot', 'spigot' => 'spigot', 'fabric' => 'fabric', 'neoforge' => 'neoforge', ]; private const MODRINTH = 'https://api.modrinth.com/v2/project/floodgate/version'; public static function status(ServerFiles $client): array { $detected = ServerPlatform::detect($client); $platform = $detected['platform'] ?? null; if ($platform === null || ! isset(self::BUILDS[$platform])) { return [ 'supported' => false, 'platform' => $platform, 'message' => $platform === 'forge' ? 'Geyser has no Forge build, so Bedrock players cannot be let into a Forge server directly.' : 'This server does not look like Paper, Spigot, Fabric or NeoForge, so there is no Geyser build for it.', ]; } $directory = $detected['directory']; $installed = self::jar($client, $directory, '/^geyser.*\.jar$/i'); return [ 'supported' => true, 'platform' => $platform, 'directory' => $directory, 'installed' => $installed, 'floodgate' => self::jar($client, $directory, '/^floodgate.*\.jar$/i'), 'floodgateAvailable' => true, 'version' => self::version('geyser'), 'port' => $installed === null ? null : self::port($client, $platform), ]; } public static function install( ServerFiles $client, bool $offlineMode, ): array { $status = self::status($client); if (! ($status['supported'] ?? false)) { return ['ok' => false, 'message' => $status['message']]; } $platform = (string) $status['platform']; $directory = (string) $status['directory']; if (! $client->pullFile($directory, sprintf(self::DOWNLOAD, 'geyser', self::BUILDS[$platform]), self::filename('Geyser', $platform), )) { return ['ok' => false, 'message' => 'The node would not accept the Geyser download.']; } $download = self::floodgate($platform); $floodgate = $download !== null && $client->pullFile($directory, $download['url'], $download['filename'], ); $allocation = self::port($client, $platform) ?? ServerPlatform::claimPort($client); if ($allocation === null) { return [ 'ok' => true, 'floodgate' => $floodgate, 'message' => 'Geyser is installing, but no port could be claimed - the server may be at its allocation limit. Add one in Network, then set it as the Bedrock port in Geyser\'s config.yml.', ]; } $authType = match (true) { $floodgate => 'floodgate', $offlineMode => 'offline', default => 'online', }; $configured = self::configure($client, $platform, $allocation['port'], $authType); if ($floodgate) { self::configureFloodgate($client, $platform); } return [ 'ok' => true, 'floodgate' => $floodgate, 'port' => $allocation['port'], 'ip' => $allocation['ip'], 'configured' => $configured, 'message' => $configured ? sprintf( 'Bedrock players can join at %s port %d once the server restarts.%s', $allocation['ip'], $allocation['port'], $floodgate ? '' : ' Floodgate could not be downloaded, so they need a Java account too.', ) : sprintf( 'Installed Geyser and claimed port %d, but its config.yml could not be written. Set the Bedrock port by hand.', $allocation['port'], ), ]; } private static function floodgate(string $platform): ?array { $build = self::FLOODGATE_BUILDS[$platform] ?? null; if ($build === null) { return null; } if ($build === 'spigot') { return [ 'url' => sprintf(self::DOWNLOAD, 'floodgate', $build), 'filename' => 'floodgate-spigot.jar', ]; } return Cache::remember("geyser:floodgate:{$build}", self::TTL, function () use ($build) { $response = Http::timeout(20)->get(self::MODRINTH, [ 'loaders' => json_encode([$build]), ]); if ($response->failed()) { return null; } $file = $response->json('0.files.0'); return $file === null ? null : [ 'url' => (string) ($file['url'] ?? ''), 'filename' => (string) ($file['filename'] ?? "floodgate-{$build}.jar"), ]; }); /* true */ } public static function floodgateDirectory(string $platform): string { return ServerPlatform::isPlugin($platform) ? '/plugins/floodgate' : '/config/floodgate'; } public static function configureFloodgate( ServerFiles $client, string $platform, ): bool { $path = self::floodgateDirectory($platform).'/config.yml'; if ($client->fileContents($path) !== null) { return true; } $config = <<<'YAML'
            # Written by the panel when Floodgate was installed. Floodgate
            # fills in the rest, including the key it shares with Geyser, the
            # first time the server starts.
            key-file-name: key.pem
            username-prefix: "."
            replace-spaces: true
            YAML; return $client->writeFile($path, $config); } public static function configDirectory(string $platform): string { return match ($platform) { 'paper', 'spigot' => '/plugins/Geyser-Spigot', 'fabric' => '/config/Geyser-Fabric', default => '/config/Geyser-NeoForge', }; } public static function configure( ServerFiles $client, string $platform, int $port, string $authType, ): bool { $path = self::configDirectory($platform).'/config.yml'; $existing = $client->fileContents($path); $config = $existing !== null && str_contains($existing, 'bedrock:') ? self::patch($existing, $port, $authType) : self::template($port, $authType); return $client->writeFile($path, $config); } private static function patch(string $config, int $port, string $authType): string { $lines = preg_split('/\r\n|\r|\n/', $config) ?: []; $section = null; foreach ($lines as $index => $line) { if (preg_match('/^([a-z0-9-]+):/i', $line, $match)) { $section = $match[1]; continue; } if (! preg_match('/^(\s+)([a-z0-9-]+):\s*(.*)$/i', $line, $match)) { continue; } [$indent, $key] = [$match[1], mb_strtolower($match[2])]; $lines[$index] = match (true) { $section === 'bedrock' && $key === 'port' => "{$indent}port: {$port}", $section === 'bedrock' && $key === 'clone-remote-port' => "{$indent}clone-remote-port: false", $section === 'remote' && $key === 'auth-type' => "{$indent}auth-type: {$authType}", default => $line, }; } return implode("\n", $lines); } private static function template(int $port, string $authType): string { return <<<YAML
            # Written by the panel when Geyser was installed. Geyser fills in
            # everything it does not find here with its own defaults.
            bedrock:
              # Must bind to all interfaces: the container's own address is
              # not reachable from outside it.
              address: 0.0.0.0
              port: {$port}
              clone-remote-port: false
            remote:
              address: auto
              port: 25565
              auth-type: {$authType}
            passthrough-motd: true
            passthrough-player-counts: true
            YAML; } private static function port( ServerFiles $client, string $platform, ): ?array { $config = $client->fileContents(self::configDirectory($platform).'/config.yml'); if ($config === null || ! preg_match('/^bedrock:\s*$(?:\n\s+.*)*?\n\s+port:\s*(\d+)/m', $config, $match)) { return null; } $port = (int) $match[1]; foreach ($client->allocations() as $allocation) { if ((int) ($allocation['port'] ?? 0) === $port) { return ['ip' => (string) ($allocation['ip'] ?? '0.0.0.0'), 'port' => $port]; } } return null; } private static function filename(string $project, string $platform): string { return match (self::BUILDS[$platform]) { 'spigot' => "{$project}-Spigot.jar", 'fabric' => "{$project}-Fabric.jar", default => "{$project}-NeoForge.jar", }; } private static function version(string $project): ?string { return Cache::remember("geyser:version:{$project}", self::TTL, function () use ($project) { $response = Http::timeout(15)->get(sprintf(self::PROJECT, $project)); if ($response->failed()) { return null; } $versions = $response->json('versions') ?? []; return $versions === [] ? null : (string) end($versions); }); } private static function jar( ServerFiles $client, string $directory, string $pattern, ): ?string { foreach ($client->listFiles($directory) ?? [] as $entry) { $name = (string) ($entry['name'] ?? ''); if (preg_match($pattern, $name)) { return $name; } } return null; } } 